import test from 'node:test';import assert from 'node:assert/strict';
import {KrakenBook,decodeBookJSON,bookChecksum,crc32} from '../public/core/kraken-book.mjs';
import {eventTimestampNs,MarketTelemetry} from '../public/core/market-telemetry.mjs';
// Independent protocol example published by Kraken, not generated by our engine.
const bids=[['45283.5','0.10000000'],['45283.4','1.54582015'],['45282.1','0.10000000'],['45281.0','0.10000000'],['45280.3','1.54592586'],['45279.0','0.07990000'],['45277.6','0.03310103'],['45277.5','0.30000000'],['45277.3','1.54602737'],['45276.6','0.15445238']].map(([price,qty])=>({price,qty}));
const asks=[['45285.2','0.00100000'],['45286.4','1.54571953'],['45286.6','1.54571109'],['45289.6','1.54560911'],['45290.2','0.15890660'],['45291.8','1.54553491'],['45294.7','0.04454749'],['45296.1','0.35380000'],['45297.5','0.09945542'],['45299.5','0.18772827']].map(([price,qty])=>({price,qty}));
const msg=()=>({channel:'book',type:'snapshot',data:[{symbol:'BTC/USD',bids,asks,checksum:3310070434}]});
test('exact decimal decoder and CRC agree with independent Kraken example',()=>{
  assert.equal(crc32('123456789'),3421780262);assert.equal(bookChecksum(asks,bids),3310070434);
  assert.deepEqual(decodeBookJSON('{"qty":0.00100000,"price":45281.0,"note":"123 \\" q"}'),{qty:'0.00100000',price:'45281.0',note:'123 " q'});
  const book=new KrakenBook({now:()=>1000});assert.equal(book.ingest(msg()),true);assert.equal(book.snapshot().checksumValid,true);assert.equal(book.snapshot().bestBid,45283.5);
});
test('bad checksum never leaves an apparently live book and updates need a new snapshot',()=>{
  const book=new KrakenBook({now:()=>1000});book.ingest(msg());const bad=msg();bad.data[0].checksum=1;
  assert.equal(book.ingest(bad),false);assert.equal(book.snapshot().checksumValid,false);assert.deepEqual(book.snapshot().bids,[]);
  const update=msg();update.type='update';assert.equal(book.ingest(update),false);assert.equal(book.ingest(msg()),true);
});
test('stale book is hidden; missing/crossed data and zero quantities are never executable',()=>{
  let now=1000;const book=new KrakenBook({now:()=>now});book.ingest(msg());now=32000;
  assert.equal(book.snapshot().status,'stale');assert.equal(book.snapshot().bestBid,null);
  const crossed=msg();crossed.data[0].bids=[{price:'50000',qty:'1'}];assert.equal(book.ingest(crossed),false);
});
test('provider microseconds are retained without presenting clock difference as proven network latency',()=>{
  const at='2026-10-13T10:00:00.123456Z';assert.equal(BigInt(eventTimestampNs(at))%1000000000n,123456000n);
  const telemetry=new MarketTelemetry({limit:3});for(const d of [10,20,30,40])telemetry.observe(at,Date.parse(at)+d);
  assert.equal(telemetry.snapshot().sample,3);assert.equal(telemetry.snapshot().p95Ms,40);assert.equal(telemetry.snapshot().clockSynchronized,false);
  assert.equal(telemetry.observe('fake',0),false);
});
